onClick:
{{
  Insert_Client_Rapide.run()
    .then((res) => {
      // 1. On sauvegarde l'ID du nouveau client
      storeValue('nouveau_client_id', res[0].ID_Client || res[0].id_client);
      // 2. On rafraîchit la base (grâce à ta nouvelle requête SQL optimisée)
      return Get_Clients_Options.run();
    })
    .then(() => {
      // 3. On FERME la modale et on ATTEND qu'elle soit bien fermée
      return closeModal('modal_add_client_rapide');
    })
    .then(() => {
      // 4. On OUVRE la modale de commande
      return showModal('modal_add_bon_de_livraison');
    })
    .then(() => {
      // 5. On force le menu déroulant à lire le nouveau client
      resetWidget('sel_client', true);
      showAlert('Client créé et sélectionné !', 'success');
    })
    .catch((err) => {
      showAlert('Erreur lors de la création : ' + err.message, 'error');
    });
}}
